export function generateEntranceQuiz(): EntranceQuizQuestion[] {
  return shuffleArray(questions)
}

export function getEntranceQuizParts(): { partNumber: number; partTitle: string }[] {
  return [
    { partNumber: 1, partTitle: "What Shape Items Look Like" },
    { partNumber: 2, partTitle: "Counting and Matching Pieces" },
    { partNumber: 3, partTitle: "Turned Pieces: Rotation Without Flipping" },
    { partNumber: 4, partTitle: "Matching Edges and Corners" },
    { partNumber: 5, partTitle: "Curves, Circles and Harder Builds" },
    { partNumber: 6, partTitle: "Strategy, Timing and Traps" },
    { partNumber: 7, partTitle: "Mastery Check" },
  ]
}
